CREATE TEMP TABLE stage_events (
  qid text PRIMARY KEY, title text, summary text,
  start_year int, start_month smallint, start_day smallint,
  end_year int, end_month smallint, end_day smallint,
  precision date_precision, display_date text, importance smallint, url text,
  event_id bigint
) ON COMMIT DROP;
CREATE TEMP TABLE stage_links (qid text, term_slug text, relevance real, is_primary boolean) ON COMMIT DROP;
CREATE TEMP TABLE stage_tags (qid text, tag_slug text) ON COMMIT DROP;

INSERT INTO stage_events (qid, title, summary, start_year, start_month, start_day, end_year, end_month, end_day, precision, display_date, importance, url) VALUES
  ('Q2671443', 'Battle of St. Lucia', 'The Battle of St. Lucia or the Battle of the Cul de Sac was a naval battle fought off the island of St.', 1778, 12, 15, NULL, NULL, NULL, 'day', '15 December 1778', 41, 'https://en.wikipedia.org/wiki/Battle_of_St._Lucia'),
  ('Q536360', 'Invasion of Tobago', 'The French invaded the British-held island of Tobago in 1781 during the Anglo-French War. On 24 May 1781, the fleet of Comte de Grasse landed troops on the island under the command of General Marquis de Bouillé.', 1781, 5, 24, 1781, 6, 2, 'day', '24 May 1781 – 2 June 1781', 34, 'https://en.wikipedia.org/wiki/Invasion_of_Tobago'),
